head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getDataLength]<br/>GridView 컴포넌트에 표시되는 데이터 Row 의 갯수를 반환합니다.",
    "validation" : [
        "렌더링 여부와 관계없이 GridView 에 바인딩되어 표시되는 데이터 Row 의 갯수를 반환해야 합니다.",
        "SubTotal Row 와 필터링, GroupBy, DrillDown 에 의해 표시되지 않는 Row 는 반환 갯수에 포함되지 않아야 합니다.",
        "데이터가 로드되지 않았거나 DataList 가 바인딩되지 않은 경우 0 을 반환해야 합니다.",
        "setRowVisible() 등의 메소드로 숨김 처리된 Row 는 반환 갯수에 포함되지 않아야 합니다.",
        "DataList 의 getRowCount() 메소드와 동일하게 동작해야 합니다.",
        "getTotalRow() 메소드는 필터링/삭제 여부와 관계없이 DataList 의 전체 Row 수를 반환하지만, getDataLength() 메소드는 필터링 적용 후 남은 Row 수를 반환해야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
// 바인딩 DataList(9건) + dept 그룹 기준 SubTotal Row(3건) 으로 구성된 GridView 동적 생성.
//  - 데이터 Row 9건(부서 3그룹 × 3건) -> dept 그룹별 SubTotal Row 3건 삽입
//  - getDataLength() 은 SubTotal Row 를 제외한 9 를 반환
//  - 필터/숨김 적용 시 getDataLength() 은 남은 표시 Row 수로 줄어듦 (getTotalRow() 과 차이점)
scwin.comp_init = async function () {
    // 기존 target/dataList 정리
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    scwin.gFilterOn = false;
    scwin.gRowHidden = false;

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] dept 컬럼 기준 SubTotal(소계) 구성. 데이터 Row 9건(부서 3그룹 × 3건) + dept 그룹별 SubTotal Row 3건이 표시됩니다.\n[확인] getDataLength() 은 SubTotal Row 를 제외한 9 를 반환합니다. 필터(dept=Sales) 적용 시 남은 3 으로, setRowVisible 로 Row 숨김 시 그만큼 줄어듭니다 (getTotalRow() 은 9 로 불변).\n[비교] DataList 의 getRowCount() 와 동일 값을 반환합니다."', '', 'label1');

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 데이터 9건 : Sales 3건 + Dev 3건 + QA 3건 -> dept 그룹 3개 -> SubTotal Row 3개 생성됨
    let jsonData = [
        { "name": "John",  "dept": "Sales", "amount": 100 },
        { "name": "Jane",  "dept": "Sales", "amount": 200 },
        { "name": "Jack",  "dept": "Sales", "amount": 300 },
        { "name": "Mike",  "dept": "Dev",   "amount": 400 },
        { "name": "Amy",   "dept": "Dev",   "amount": 500 },
        { "name": "Alex",  "dept": "Dev",   "amount": 600 },
        { "name": "Tom",   "dept": "QA",    "amount": 700 },
        { "name": "Tina",  "dept": "QA",    "amount": 800 },
        { "name": "Tony",  "dept": "QA",    "amount": 900 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind"
    };
    let cList = $c.gcm.createCList(properties);

    // Header(이름/부서/금액) + gBody(데이터) + SubTotal(부서별 소계)
    // - SubTotal : targetColumnID="dept" -> dept 가 바뀔 때마다 소계 Row 삽입, amount 에 sum('amount') expression
    // - 마지막 컬럼 width="*" 로 가로 스크롤 방지
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="SubTotal 바인딩 그리드 (데이터 9건 + SubTotal 3건)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol1" value="이름"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol2" value="부서"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol3" value="금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="amount" dataList="amount"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    // SubTotal : dept 기준 소계 Row (dept 값이 바뀌는 지점마다 삽입)
    strTarget += '<w2:subTotal style="" id="subTotal1" targetColumnID="dept">';
    strTarget += '<w2:row style="" id="srow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="scol1" value="소계(SubTotal)"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="scol2" value=""></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="expression" dataType="number" displayFormat="#,###" id="scol3" expression="sum(\'amount\')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:subTotal>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);
}



// getDataLength 확인 — GridView 에 표시되는 데이터 Row 갯수 반환 (SubTotal Row 3건 미포함 → 9)
// DataList 의 getRowCount() 와 동일 값을 반환하는지 함께 비교 출력
scwin.btn_getDataLength_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("getDataLength() : " + target1.getDataLength() + " / dlt_bind.getRowCount() : " + dlt_bind.getRowCount());
}



// 필터 적용/해제 — dept 컬럼을 'Sales' 로 필터링.
// getDataLength() 은 필터 적용 후 남은 3 으로 줄지만, getTotalRow() 은 전체 9 로 불변 (차이점 검증)
scwin.btn_toggleFilter_onclick = function () {
    if (scwin.gFilterOn === true) {
        dlt_bind.removeColumnFilterAll();
        scwin.gFilterOn = false;
        wf_body_bottom.getObj("scwin").setReturnValue("[필터 해제 후] getDataLength() : " + target1.getDataLength() + " / getTotalRow() : " + target1.getTotalRow());
    } else {
        // 4번째 인자 exactMatch=true 필요 — (colID, dataValue) 2-인자만으로는 필터가 적용되지 않음
        dlt_bind.setColumnFilter("dept", "Sales", "and", true);
        scwin.gFilterOn = true;
        wf_body_bottom.getObj("scwin").setReturnValue("[dept='Sales' 필터 적용 후] getDataLength() : " + target1.getDataLength() + " (남은 3) / getTotalRow() : " + target1.getTotalRow() + " (전체 9 불변)");
    }
}



// Row 숨김 적용/해제 — setRowVisible() 로 첫번째 데이터 Row(인덱스 0) 숨김 처리.
// 숨김 Row 는 getDataLength() 반환 갯수에 포함되지 않음
scwin.btn_toggleRowVisible_onclick = function () {
    if (scwin.gRowHidden === true) {
        target1.setRowVisible(0, true);
        scwin.gRowHidden = false;
        wf_body_bottom.getObj("scwin").setReturnValue("[Row 숨김 해제 후] getDataLength() : " + target1.getDataLength());
    } else {
        target1.setRowVisible(0, false);
        scwin.gRowHidden = true;
        wf_body_bottom.getObj("scwin").setReturnValue("[Row 0 숨김 적용 후] getDataLength() : " + target1.getDataLength() + " (숨김 Row 제외)");
    }
}



// 데이터 미바인딩 확인 — DataList 데이터를 비워(빈 배열) 표시 Row 가 없는 경우 0 반환
scwin.btn_emptyData_onclick = function () {
    dlt_bind.removeColumnFilterAll();
    scwin.gFilterOn = false;
    scwin.gRowHidden = false;
    dlt_bind.setJSON([], false);
    wf_body_bottom.getObj("scwin").setReturnValue("[데이터 미로드 시] getDataLength() : " + target1.getDataLength());
}
